$message='';$done=false;
try{$count=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();if($count>0){$message='An administrator account already exists. For safety, remove setup-admin.php from your local project.';$done=true;}elseif($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=post_string('name',100);$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(!$email||mb_strlen($name)<2||strlen($password)<12)throw new RuntimeException('Use a valid email, name and a password of at least 12 characters.');$pdo=db();$pdo->prepare("INSERT INTO users(full_name,email,phone,password_hash,role,status) VALUES(?,?, '', ?, 'admin','active')")->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO user_profiles(user_id) VALUES(?)')->execute([$id]);$message='Administrator account created. Remove setup-admin.php now and sign in.';$done=true;}}catch(Throwable $e){$message=$e->getMessage();}
